@dataclass
class SessionConfig:
    """Configuration for sliding session behavior.
    
    Attributes:
        max_age: Session expires after this many seconds of inactivity. Default: 3600 (1 hour)
        sliding: If True, refresh session expiry on each request. Default: True
        absolute_max: Optional hard limit in seconds regardless of activity. Default: None
        secure: If True, cookie only sent over HTTPS. Default: True
        same_site: SameSite cookie policy ('lax', 'strict', 'none'). Default: 'lax'
        http_only: If True, cookie not accessible via JavaScript. Default: True
        
    Example:
        >>> config = SessionConfig()  # 1 hour inactivity timeout, sliding enabled
        >>> config = SessionConfig(max_age=1800)  # 30 min inactivity timeout
        >>> config = SessionConfig(max_age=3600, absolute_max=86400)  # 1h sliding, 24h hard limit
    """
    max_age: int = 3600  # 1 hour inactivity timeout
    sliding: bool = True  # Refresh on each request
    absolute_max: int = None  # Optional hard limit (e.g., 86400 for 24h)
    secure: bool = True  # HTTPS-only in production
    same_site: str = 'lax'  # CSRF protection
    http_only: bool = True  # No JS access
    
    @classmethod
    def default(cls) -> 'SessionConfig':
        """Standard sliding session: 1 hour inactivity timeout."""
        return cls()
    
    @classmethod
    def strict(cls) -> 'SessionConfig':
        """Strict session: 30 min inactivity, 8 hour hard limit."""
        return cls(max_age=1800, absolute_max=28800)
    
    @classmethod
    def relaxed(cls) -> 'SessionConfig':
        """Relaxed session: 8 hour inactivity, 7 day hard limit."""
        return cls(max_age=28800, absolute_max=604800)

