class SlidingSessionMiddleware(SessionMiddleware):
    """Session middleware with sliding expiry.
    
    Extends Starlette's SessionMiddleware to refresh the session cookie
    max_age on each request, implementing sliding session expiry.
    
    Sessions expire after `max_age` seconds of INACTIVITY, not from login time.
    
    Args:
        app: ASGI application
        secret_key: Secret key for signing cookies
        session_config: SessionConfig instance for timeout settings
        session_cookie: Cookie name. Default: 'session'
        path: Cookie path. Default: '/'
        
    Example:
        >>> from starlette.applications import Starlette
        >>> app = Starlette()
        >>> config = SessionConfig(max_age=3600)  # 1 hour inactivity
        >>> app = SlidingSessionMiddleware(app, secret_key='...', session_config=config)
    """
    
    def __init__(
        self,
        app,
        secret_key: str,
        session_config: SessionConfig = None,
        session_cookie: str = "session",
        path: str = "/",
    ):
        self.config = session_config or SessionConfig.default()
        
        # Initialize parent with config values
        super().__init__(
            app,
            secret_key=secret_key,
            session_cookie=session_cookie,
            max_age=self.config.max_age,
            path=path,
            same_site=self.config.same_site,
            https_only=self.config.secure,
        )
        self._config = self.config  # Store for access in __call__
    
    async def __call__(self, scope, receive, send):
        """Process request and refresh session cookie on response."""
        if scope["type"] not in ("http", "websocket"):
            await self.app(scope, receive, send)
            return
        
        # Load existing session
        connection = (scope["type"] == "http") and scope or None
        if connection:
            # Standard session loading from parent
            initial_session_was_empty = True
            scope["session"] = {}
            
            # Try to load existing session from cookie
            if self.session_cookie in scope.get("headers", []):
                pass  # Will be loaded by parent
        
        # Let parent handle the request
        async def send_wrapper(message):
            """Wrap send to refresh session cookie max_age."""
            if message["type"] == "http.response.start":
                # Check if session has user_id (authenticated)
                session = scope.get("session", {})
                
                if session.get("user_id") and self._config.sliding:
                    # Check absolute max if configured
                    if self._config.absolute_max:
                        session_started = session.get("session_started_at", 0)
                        if session_started and (time.time() - session_started > self._config.absolute_max):
                            # Absolute max exceeded - clear session
                            session.clear()
                            logger.info("Session absolute max exceeded, forcing logout")
                    
                    # Session is valid - cookie will be refreshed with new max_age
                    # The parent class handles setting the cookie with max_age
                    logger.debug(f"Sliding session refresh for user {session.get('user_id')}")
            
            await send(message)
        
        await super().__call__(scope, receive, send_wrapper)


def create_session_middleware(
    secret_key: str,
    session_config: SessionConfig = None,
    session_cookie: str = "session",
) -> SlidingSessionMiddleware:
    """Factory to create SlidingSessionMiddleware for FastHTML apps.
    
    Args:
        secret_key: Secret key for signing session cookies (required)
        session_config: SessionConfig instance. Default: SessionConfig.default()
        session_cookie: Cookie name. Default: 'session'
        
    Returns:
        Configured SlidingSessionMiddleware instance
        
    Example:
        >>> from fasthtml.common import FastHTML
        >>> 
        >>> # Create app WITHOUT default session middleware
        >>> app = FastHTML(sess_cls=None)  # Disable default sessions
        >>> 
        >>> # Add sliding session middleware
        >>> config = SessionConfig(max_age=3600)  # 1 hour inactivity
        >>> app = create_session_middleware('your-secret-key', config)(app)
        >>>
        >>> # Or wrap during app creation (recommended)
        >>> middleware = create_session_middleware('your-secret-key', config)
        >>> # Then configure FastHTML to use it
        
    Note:
        FastHTML's default SessionMiddleware needs to be disabled first.
        See integration documentation for patterns.
    """
    config = session_config or SessionConfig.default()
    
    def middleware_factory(app):
        return SlidingSessionMiddleware(
            app,
            secret_key=secret_key,
            session_config=config,
            session_cookie=session_cookie,
        )
    
    return middleware_factory

